SELECT COUNT(*)
FROM agent_run
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
  AND status = 'SUCCEEDED'

SELECT run_id, tenant_id, user_id, session_id, request_id, trigger_type, status, model,
       input_summary, output_summary, error_code, duration_ms
FROM agent_run
WHERE user_id = #{userId}
  AND tenant_id = #{tenantId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit}

SELECT run_id, tenant_id, user_id, session_id, request_id, trigger_type, status, model,
       input_summary, output_summary, error_code, duration_ms, started_at, finished_at
FROM agent_run


        AND user_id = #{userId}


        AND session_id = #{sessionId}


        AND status = #{status}


ORDER BY created_at DESC, id DESC
LIMIT #{limit}
